      pruefungsfallen: [
        'Das basale TSH ist der Screening-Parameter Nummer 1 — es muss ZUERST genannt werden. Wer mit fT3/fT4 oder gar mit dem Ultraschall beginnt, wird korrigiert. Merke: TSH supprimiert + fT3/fT4 erhöht = manifeste Hyperthyreose.',
        'In Freiburg (18.03.2025) spielte die Prüferin die Patientin UND stellte bereits WÄHREND der Anamnese Fachfragen (\'Was ist Ihre Verdachtsdiagnose? Warum denken Sie an eine Hyperthyreose, wenn sie keinen Kropf hat?\'). Man muss also mitten in der Anamnese umschalten und argumentieren können — und zwar auch OHNE Struma: die Diagnose stützt sich auf die Symptomkonstellation, nicht auf den Kropf. Eine Struma ist bei Morbus Basedow keineswegs obligat.',
        'Die Palpation der Schilddrüse gehört unbedingt in die körperliche Untersuchung, und es muss ausdrücklich gesagt werden, dass die Patientin dabei SCHLUCKEN muss (in Freiburg 09.01.2024 wörtlich verlangt). Ideal: von hinten mit beiden Händen, dazu Auskultation auf ein Schwirren.',
        'Die Szintigraphie erfolgt VOR jeder Punktion. Heißer Knoten = mehrspeichernd, praktisch nie maligne, wird nicht punktiert; kalter Knoten = nicht speichernd, malignitätsverdächtig, wird punktiert. Diese Frage wurde in Freiburg mehrfach gestellt und nur \'teilweise richtig\' beantwortet.',
        '\'Hat das Jodsalz etwas damit zu tun?\' ist eine Fangfrage: Normales jodiertes Speisesalz löst keinen Morbus Basedow aus und muss nicht gemieden werden; relevant ist die hochdosierte Jodexposition durch Kontrastmittel, Amiodaron oder Jodpräparate — sie kann eine Autonomie dekompensieren lassen und eine thyreotoxische Krise auslösen.',
        'Die endokrine Orbitopathie kommt beim Morbus Basedow vor, NICHT bei der funktionellen Autonomie — sie ist damit ein klinisches Unterscheidungsmerkmal. Beweisend für den Basedow sind die TRAK.',
        'Die Agranulozytose unter Thiamazol muss aktiv genannt werden: Blutbildkontrollen und die Anweisung an die Patientin, bei Fieber, Halsschmerzen oder Aphthen sofort das Medikament abzusetzen und sich vorzustellen. Wer nur \'Thyreostatikum\' sagt, verschenkt Punkte.',
        'Bei dieser Patientin mit Diabetes mellitus Typ 1: Der Betablocker verschleiert die Warnsymptome einer Unterzuckerung — das muss erwähnt werden. Und auf ihre Frage \'Muss mein Insulin reduziert werden, weil ich abgenommen habe?\' lautet die Antwort NICHT einfach ja: die Dosis wird ärztlich gesteuert angepasst, und mit erreichter Euthyreose steigt der Bedarf meist wieder an.',
        'Der Flush wird von der Patientin ausdrücklich verneint — das ist das entscheidende Argument gegen das Karzinoid, das in Freiburg als DD genannt und dann hinterfragt wurde (\'Warum denken Sie an ein Karzinoid? Wo sitzt es am häufigsten?\' — Antwort: Appendix/Wurmfortsatz; heute spricht man von neuroendokrinen Tumoren, NET).',
        'Frage aus Stuttgart 13.11.2023: \'Können denn nur Frauen an einer Schilddrüsenüberfunktion erkranken?\' — Nein: Frauen sind etwa fünfmal häufiger betroffen, Männer erkranken aber ebenfalls und oft mit schwererem Verlauf. Patientengerecht und ohne Fachjargon antworten.',
        'In der Frühphase der Therapie darf NICHT nach dem TSH gesteuert werden — es bleibt noch Wochen bis Monate supprimiert. Gesteuert wird nach fT3 und fT4.',
        'Der Rauchstopp ist bei dieser Patientin (30 Packungsjahre) nicht nur eine allgemeine Empfehlung, sondern eine gezielte Therapiemaßnahme wegen der endokrinen Orbitopathie — das wird von den Prüfern honoriert. \'Packungsjahre\' immer ausschreiben, im Gespräch niemals abkürzen.',
        'Mehrere Kandidaten konnten den Namen des Thyreostatikums oder die Definition von heißen und kalten Knoten nicht nennen und haben trotzdem bestanden: \'es geht nur um die Sprache\'. Bei einer Wissenslücke ruhig bleiben, das Gesagte sprachlich sauber strukturieren und die Lücke offen benennen, statt zu raten.',
        'Die Patientin bietet den Arbeitsstress selbst als Erklärung an und lenkt ständig auf ihren Diabetes. Sie darf nicht darin bestätigt werden — die Somatisierung ist erst nach Ausschluss der organischen Ursache eine Diagnose; gleichzeitig muss man sie ernst nehmen und beruhigen (sie hat unausgesprochen Angst vor Krebs).',
      ],
